const G_MODES = ['blitz', 'memory', 'type', 'cast', 'cards'];
const gModeOn = k => { const m = cfg('quizModes'); return !m || m[k] !== false; };
const gDay = () => Math.floor((Date.now() - new Date().getTimezoneOffset() * 60000) / 864e5);
